// Locks accounts in the order they were passed in
void transfer(Account *from, Account *to, int amount) {
    lock(from->mutex);
    lock(to->mutex);
    from->balance -= amount;
    to->balance += amount;
    unlock(to->mutex);
    unlock(from->mutex);
}

// Caller one, on thread 1
transfer(accountA, accountB, 50);

// Caller two, on thread 2, running at the same time
transfer(accountB, accountA, 30);

