// Always locks the two accounts in a fixed global order,
// regardless of which one is logically the "from" account.
void transfer(Account *from, Account *to, int amount) {
    Account *first  = (from->id < to->id) ? from : to;
    Account *second = (from->id < to->id) ? to : from;

    lock(first->mutex);
    lock(second->mutex);

    from->balance -= amount;
    to->balance += amount;

    unlock(second->mutex);
    unlock(first->mutex);
}

